import { atom, read, update } from 'claude-code'
import type { Register, Timer } from 'claude-code'

import type { MeshyKind, MeshyTask } from '../types'
import {
  BASE_URL,
  ENDPOINTS,
  KIND_LABELS,
  MeshyError,
  describeImage,
  formatElapsed,
  imageMime,
  isActive,
  isRemoteImage,
  keyFromDotenv,
  parseResponse,
  progressBar,
  shortId,
  statusLabel,
} from './meshy'
import type { MeshyTaskObject } from './meshy'

const PANE = 'meshy-tasks'
const TOOL_NAME = 'meshy_generate'
const TOOL = 'mcp__meshy-tray__meshy_generate'
const TICK_MS = 1000
const POLL_EVERY_TICKS = 5
const TOAST_MS = 8000
const MAX_TASKS = 100

const tasks = atom({ plugin: 'meshy-tray', key: 'tasks' } as const, [])

const MODES: Record<string, MeshyKind> = {
  'image-to-3d': 'image',
  'text-to-3d': 'text',
  'multi-image-to-3d': 'multi',
}

const INPUT_SCHEMA = {
  type: 'object',
  properties: {
    mode: {
      type: 'string',
      enum: Object.keys(MODES),
      description: 'Which Meshy generation to start.',
    },
    prompt: {
      type: 'string',
      description: 'text-to-3d: what to make (max 800 characters).',
    },
    image: {
      type: 'string',
      description:
        'image-to-3d: a local .png/.jpg/.jpeg path (relative to the working directory or absolute, up to 4 MiB), an https URL, or a data URI.',
    },
    images: {
      type: 'array',
      items: { type: 'string' },
      minItems: 1,
      maxItems: 4,
      description:
        'multi-image-to-3d: 1 to 4 views of the same object, each a local path, URL or data URI; the first is the front view.',
    },
    ai_model: {
      type: 'string',
      description: 'meshy-6-lite, meshy-6, meshy-7.1 or latest (the default).',
    },
    texture: {
      type: 'boolean',
      description:
        'Default true. image and multi-image: should_texture. text-to-3d: run the refine (texturing) stage after the untextured preview.',
    },
    texture_prompt: { type: 'string', description: 'Guides texturing (max 800 characters).' },
    enable_pbr: { type: 'boolean', description: 'Also generate metallic, roughness and normal maps.' },
    should_remesh: { type: 'boolean' },
    topology: { type: 'string', enum: ['triangle', 'quad'] },
    target_polycount: { type: 'integer', minimum: 100, maximum: 300000 },
    pose_mode: { type: 'string', enum: ['', 'a-pose', 't-pose'] },
    options: {
      type: 'object',
      description:
        'Any other Meshy create-request fields (e.g. geometry_resolution, texture_resolution, auto_size), sent as given.',
    },
  },
  required: ['mode'],
}

const DESCRIPTION = [
  'Start a Meshy 3D generation: image-to-3d (one image), text-to-3d (a prompt) or multi-image-to-3d (1-4 views).',
  'Returns the task id at once; the task runs in the background, shown in the band above the prompt.',
  'When it succeeds the GLB is saved to ./meshy-models/<task-id>.glb and the user gets a toast; do not poll or wait for it.',
  'The user can list tasks with /meshy-tasks. Each generation spends Meshy credits.',
].join(' ')

type Args = Record<string, unknown>

type Plan = {
  kind: MeshyKind
  body: Record<string, unknown>
  source: string
  images: string[]
  imageField?: 'image_url' | 'image_urls'
  shouldRefine?: boolean
  refineOptions?: Record<string, string | number | boolean>
}

const str = (value: unknown) => (typeof value === 'string' && value.trim() ? value.trim() : undefined)

/** The optional create fields the tool's schema names, when given. */
const commonFields = (args: Args) => {
  const fields: Record<string, unknown> = {}
  for (const name of ['ai_model', 'should_remesh', 'topology', 'target_polycount', 'pose_mode']) {
    if (args[name] !== undefined) fields[name] = args[name]
  }
  const options = args.options
  if (options && typeof options === 'object' && !Array.isArray(options)) {
    Object.assign(fields, options)
  }

  return fields
}

const textureFields = (args: Args) => {
  const fields: Record<string, string | number | boolean> = {}
  if (typeof args.enable_pbr === 'boolean') fields.enable_pbr = args.enable_pbr
  const prompt = str(args.texture_prompt)
  if (prompt) fields.texture_prompt = prompt

  return fields
}

/** The request a tool call asks for, its images still as given. */
const plan = (args: Args): Plan => {
  const kind = MODES[String(args.mode)]
  if (!kind) throw new Error(`mode must be one of ${Object.keys(MODES).join(', ')}`)

  if (kind === 'text') {
    const prompt = str(args.prompt)
    if (!prompt) throw new Error('text-to-3d needs a prompt')

    return {
      kind,
      source: prompt,
      images: [],
      body: { ...commonFields(args), mode: 'preview', prompt },
      shouldRefine: args.texture !== false,
      refineOptions: textureFields(args),
    }
  }

  const body = {
    ...commonFields(args),
    ...textureFields(args),
    ...(typeof args.texture === 'boolean' ? { should_texture: args.texture } : {}),
  }

  if (kind === 'image') {
    const image = str(args.image)
    if (!image) throw new Error('image-to-3d needs an image (a local path or a URL)')

    return { kind, source: describeImage(image), images: [image], imageField: 'image_url', body }
  }

  const images = Array.isArray(args.images) ? (args.images.map(str).filter(Boolean) as string[]) : []
  if (images.length < 1 || images.length > 4) {
    throw new Error('multi-image-to-3d needs 1 to 4 images')
  }

  return { kind, source: images.map(describeImage).join(', '), images, imageField: 'image_urls', body }
}

const errorText = (error: unknown) => (error instanceof Error ? error.message : String(error))

export const register: Register = (on, options) => {
  // Built in session.start over the session's own `$`, which outlives any one
  // dispatch; the tool call hands its work to it.
  let generate: ((args: Args) => Promise<string>) | undefined
  let timer: Timer | undefined
  let ticks = 0
  let isPolling = false
  const downloading = new Set<string>()

  on('session.start', async ($, e, next) => {
    const loadKey = async () => {
      // The plugin's own option (kept in secure storage), else the environment, else the project's .env.
      const fromOptions = typeof options.meshy_api_key === 'string' ? options.meshy_api_key.trim() : ''
      if (fromOptions) return fromOptions
      const fromEnv = (await $.env.get('MESHY_API_KEY'))?.trim()
      if (fromEnv) return fromEnv
      for (const dir of new Set([await $.session.cwd(), await $.session.root()])) {
        const path = `${dir}/.env`
        if (!(await $.fs.exists(path))) continue
        const key = keyFromDotenv(await $.fs.read(path))
        if (key) return key
      }

      return undefined
    }

    const request = async (key: string, method: 'GET' | 'POST', path: string, body?: unknown) => {
      const response = await $.http.fetch(`${BASE_URL}${path}`, {
        method,
        headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
        body: body === undefined ? undefined : JSON.stringify(body),
      })

      return parseResponse(response, key)
    }

    const toImageUrl = async (image: string) => {
      if (isRemoteImage(image)) return image
      const mime = imageMime(image)
      const path = image.startsWith('/') ? image : `${await $.session.cwd()}/${image}`
      if (!(await $.fs.exists(path))) throw new Error(`${image}: no such file`)
      try {
        const { base64 } = await $.fs.read(path, { as: 'bytes' })

        return `data:${mime};base64,${base64}`
      } catch {
        throw new Error(`${image}: could not be read (files over 4 MiB cannot be sent; pass a URL instead)`)
      }
    }

    const patch = (id: string, change: Partial<MeshyTask>) =>
      update($, tasks, list => list.map(task => (task.id === id ? { ...task, ...change } : task)))

    const fail = async (task: MeshyTask, message: string) => {
      await patch(task.id, { status: 'FAILED', error: message, finishedAt: await $.clock.now() })
      $.ui.toast(`Meshy ${KIND_LABELS[task.kind]} ${shortId(task.id)} failed: ${message}`, {
        timeoutMs: TOAST_MS,
      })
    }

    const download = async (task: MeshyTask, key: string) => {
      if (downloading.has(task.id)) return
      downloading.add(task.id)
      try {
        // Asked again here so a download restarted after a reload gets a fresh signed URL.
        const object = (await request(key, 'GET', `${ENDPOINTS[task.kind]}/${task.apiId}`)) as MeshyTaskObject
        const url = object.model_urls?.glb
        if (!url) {
          await fail(task, 'the task succeeded but returned no GLB')
          return
        }
        const relative = `meshy-models/${task.id}.glb`
        // The asset URL is pre-signed: the key never reaches curl's argv.
        const ran = await $.process.run(
          ['curl', '-fsSL', '--retry', '2', '--create-dirs', '-o', relative, url],
          { cwd: task.cwd, timeoutMs: 10 * 60 * 1000 },
        )
        if (ran.exitCode !== 0) {
          await fail(task, `download failed: ${ran.stderr.trim() || `curl exited ${ran.exitCode}`}`)
          return
        }
        const file = `./${relative}`
        await patch(task.id, { status: 'SUCCEEDED', progress: 100, file, finishedAt: await $.clock.now() })
        $.ui.toast(`Meshy model ready: ${file}`, { timeoutMs: TOAST_MS })
      } catch (error) {
        await fail(task, `download failed: ${errorText(error)}`)
      } finally {
        downloading.delete(task.id)
      }
    }

    const poll = async (task: MeshyTask, key: string) => {
      let object: MeshyTaskObject
      try {
        object = (await request(key, 'GET', `${ENDPOINTS[task.kind]}/${task.apiId}`)) as MeshyTaskObject
      } catch (error) {
        // A rate limit, a 5xx or a network blip is retried next round.
        const isFinal =
          error instanceof MeshyError && error.status >= 400 && error.status < 500 && error.status !== 429
        if (isFinal) await fail(task, error.message)
        return
      }

      if (object.status === 'PENDING' || object.status === 'IN_PROGRESS') {
        await patch(task.id, { status: object.status, progress: object.progress ?? 0 })
        return
      }
      if (object.status === 'FAILED' || object.status === 'CANCELED') {
        const fallback = object.status === 'CANCELED' ? 'canceled' : 'no reason given'
        await fail(task, object.task_error?.message || fallback)
        return
      }
      if (object.status !== 'SUCCEEDED') return

      if (task.kind === 'text' && task.stage === 'preview' && task.shouldRefine) {
        try {
          const created = (await request(key, 'POST', ENDPOINTS.text, {
            ...task.refineOptions,
            mode: 'refine',
            preview_task_id: task.apiId,
          })) as { result?: string }
          if (!created?.result) throw new Error('Meshy returned no task id')
          await patch(task.id, { apiId: created.result, stage: 'refine', status: 'PENDING', progress: 0 })
        } catch (error) {
          await fail(task, `refine: ${errorText(error)}`)
        }
        return
      }

      await patch(task.id, { status: 'DOWNLOADING', progress: 100 })
      await download(task, key)
    }

    const tick = async () => {
      const active = (await read($, tasks)).filter(isActive)
      if (active.length === 0) {
        timer?.cancel()
        timer = undefined
        return
      }
      // The elapsed times move every second; the state only every poll.
      $.ui.invalidate('ui.render')
      ticks += 1
      if (isPolling || ticks % POLL_EVERY_TICKS !== 0) return
      const key = await loadKey()
      if (!key) return
      isPolling = true
      try {
        await Promise.all(
          active.map(task => (task.status === 'DOWNLOADING' ? download(task, key) : poll(task, key))),
        )
      } finally {
        isPolling = false
      }
    }

    const ensureTicking = () => {
      if (timer) return
      ticks = 0
      timer = $.clock.every(TICK_MS, () => void tick())
    }

    generate = async args => {
      const key = await loadKey()
      if (!key) {
        throw new Error('MESHY_API_KEY is not set: export it, or add MESHY_API_KEY=... to the project .env file')
      }
      const planned = plan(args)
      const imageUrls: string[] = []
      for (const image of planned.images) imageUrls.push(await toImageUrl(image))
      const body =
        planned.imageField === 'image_url'
          ? { ...planned.body, image_url: imageUrls[0] }
          : planned.imageField === 'image_urls'
            ? { ...planned.body, image_urls: imageUrls }
            : planned.body
      const answer = (await request(key, 'POST', ENDPOINTS[planned.kind], body)) as { result?: string }
      const id = answer?.result
      if (!id) throw new Error('Meshy returned no task id')

      const task: MeshyTask = {
        id,
        kind: planned.kind,
        apiId: id,
        status: 'PENDING',
        progress: 0,
        source: planned.source,
        cwd: await $.session.cwd(),
        startedAt: await $.clock.now(),
        ...(planned.kind === 'text'
          ? { stage: 'preview' as const, shouldRefine: planned.shouldRefine, refineOptions: planned.refineOptions }
          : {}),
      }
      await update($, tasks, list => [...list, task].slice(-MAX_TASKS))
      ensureTicking()

      const stages = planned.kind === 'text' && planned.shouldRefine ? ' (preview, then texturing)' : ''

      return `Started ${String(args.mode)} task ${id}${stages}. It runs in the background and shows in the band above the prompt; when it succeeds the model is saved to ./meshy-models/${id}.glb and the user is notified. Do not poll for it.`
    }

    await $.tool.register({ name: TOOL_NAME, description: DESCRIPTION, inputSchema: INPUT_SCHEMA })
    await $.command.register({
      name: 'meshy-tasks',
      description: "List this session's Meshy generations in a pane",
    })
    // Tasks kept in $.state outlive a reload; pick their polling back up.
    if ((await read($, tasks)).some(isActive)) ensureTicking()

    return next(e)
  })

  on('tool.call', { tool: TOOL }, async (_$, e) => {
    if (!generate) return { deny: 'meshy-tray is still starting; try again in a moment.' }
    try {
      return { result: await generate(e as Args) }
    } catch (error) {
      return { deny: `meshy_generate: ${errorText(error)}` }
    }
  })

  on('command.run', { command: 'meshy-tasks' }, async $ => {
    await $.ui.open({ id: PANE, title: 'Meshy tasks', closeOnEscape: true })

    return { text: 'Opened the Meshy tasks pane.' }
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)
    const active = (await read($, tasks)).filter(isActive)
    if (active.length === 0) return next(e)

    const { Box, Text } = $.ui.resolve(e)
    const now = await $.clock.now()

    return (
      <Box flexDirection="column">
        {active.map(task => {
          const { filled, track } = progressBar(task.progress)

          return (
            <Box key={task.id} flexDirection="row">
              <Text>
                {KIND_LABELS[task.kind].padEnd(6)}
                {shortId(task.id)} {statusLabel(task).padEnd(8)}{' '}
              </Text>
              <Text color="cyan">{filled}</Text>
              <Text dimColor>{track}</Text>
              <Text>{` ${`${task.progress}%`.padStart(4)} `}</Text>
              <Text dimColor>{formatElapsed(now - task.startedAt)}</Text>
            </Box>
          )
        })}
      </Box>
    )
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text } = $.ui.resolve(e)
    const list = [...(await read($, tasks))].reverse()
    const now = await $.clock.now()

    if (list.length === 0) {
      return (
        <Box flexDirection="column">
          <Text dimColor>No Meshy tasks in this session yet.</Text>
          <Text dimColor>Ask Claude to make a 3D model; it calls meshy_generate.</Text>
        </Box>
      )
    }

    const running = list.filter(isActive).length

    return (
      <Box flexDirection="column">
        <Text dimColor>
          {list.length} task{list.length === 1 ? '' : 's'}, {running} running
        </Text>
        {list.map(task => {
          const color =
            task.status === 'SUCCEEDED' ? 'green' : task.status === 'FAILED' || task.status === 'CANCELED' ? 'red' : 'cyan'
          const elapsed = formatElapsed((task.finishedAt ?? now) - task.startedAt)

          return (
            <Box key={task.id} flexDirection="column" marginTop={1}>
              <Box flexDirection="row">
                <Text bold>{`${KIND_LABELS[task.kind]} ${shortId(task.id)} `}</Text>
                <Text color={color}>{statusLabel(task)}</Text>
                <Text>{isActive(task) ? ` ${task.progress}%` : ''} </Text>
                <Text dimColor>{elapsed}</Text>
              </Box>
              <Text dimColor wrap="truncate-end">
                {`${task.kind === 'text' ? 'prompt' : 'image'}: ${task.source}`}
              </Text>
              {task.file ? <Text wrap="truncate-start">{`file: ${task.file}`}</Text> : null}
              {task.error ? <Text color="red">{`error: ${task.error}`}</Text> : null}
              <Text dimColor wrap="truncate">{`id: ${task.id}`}</Text>
            </Box>
          )
        })}
      </Box>
    )
  })
}

