import type { HttpResponse } from 'claude-code'

import type { MeshyKind, MeshyStatus, MeshyTask } from '../types'

export const BASE_URL = 'https://api.meshy.ai'

// Create and retrieve share a path per kind: POST <path>, GET <path>/<id>.
export const ENDPOINTS: Record<MeshyKind, string> = {
  image: '/openapi/v1/image-to-3d',
  multi: '/openapi/v1/multi-image-to-3d',
  text: '/openapi/v2/text-to-3d',
}

export const KIND_LABELS: Record<MeshyKind, string> = {
  image: 'image',
  multi: 'multi',
  text: 'text',
}

export type MeshyTaskObject = {
  id: string
  status: MeshyStatus
  progress?: number
  model_urls?: { glb?: string }
  task_error?: { message?: string }
}

export class MeshyError extends Error {
  status: number

  constructor(status: number, message: string) {
    super(message)
    this.status = status
  }
}

/** True while the task still needs polling or downloading. */
export const isActive = (task: MeshyTask) =>
  task.status === 'PENDING' ||
  task.status === 'IN_PROGRESS' ||
  task.status === 'DOWNLOADING'

/** The last 8 characters: Meshy ids are UUIDv7, so their heads repeat. */
export const shortId = (id: string) => id.replace(/-/g, '').slice(-8)

const LEVELS = ['▁', '▂', '▃', '▄', '▅', '▆', '▇', '█']

/**
 * A bar `width` cells wide: full cells, one partial cell from the eighths,
 * and the empty track, returned apart so the track can be drawn dim.
 */
export const progressBar = (percent: number, width = 10) => {
  const eighths = Math.round((Math.max(0, Math.min(100, percent)) / 100) * width * 8)
  const full = Math.floor(eighths / 8)
  const part = eighths % 8
  const filled = '█'.repeat(full) + (part > 0 ? LEVELS[part - 1] : '')

  return { filled, track: '▁'.repeat(width - filled.length) }
}

export const formatElapsed = (ms: number) => {
  const seconds = Math.max(0, Math.floor(ms / 1000))
  if (seconds < 60) return `${seconds}s`
  const minutes = Math.floor(seconds / 60)
  if (minutes < 60) return `${minutes}m${String(seconds % 60).padStart(2, '0')}s`

  return `${Math.floor(minutes / 60)}h${String(minutes % 60).padStart(2, '0')}m`
}

export const statusLabel = (task: MeshyTask) => {
  if (task.status === 'PENDING') return 'queued'
  if (task.status === 'DOWNLOADING') return 'saving'
  if (task.status === 'IN_PROGRESS') return task.stage ?? 'running'

  return task.status.toLowerCase()
}

/** Reads MESHY_API_KEY from a .env file's text, or undefined. */
export const keyFromDotenv = (text: string) => {
  for (const line of text.split(/\r?\n/)) {
    const match = /^\s*(?:export\s+)?MESHY_API_KEY\s*=\s*(.*)$/.exec(line)
    if (!match) continue
    let value = (match[1] ?? '').trim()
    const quote = value[0]
    if ((quote === '"' || quote === "'") && value.indexOf(quote, 1) > 0) {
      value = value.slice(1, value.indexOf(quote, 1))
    } else {
      value = value.replace(/\s+#.*$/, '')
    }
    if (value) return value
  }

  return undefined
}

/** Never lets the key reach a message, whatever an error echoes back. */
export const scrub = (text: string, key: string) =>
  key ? text.split(key).join('***') : text

/** A Meshy response's JSON, or a MeshyError with the API's own message. */
export const parseResponse = (response: HttpResponse, key: string): unknown => {
  let json: unknown
  try {
    json = JSON.parse(response.text)
  } catch {
    json = undefined
  }
  if (!response.ok) {
    const message = (json as { message?: unknown } | undefined)?.message
    const text = typeof message === 'string' && message ? message : 'request failed'
    throw new MeshyError(response.status, scrub(`${text} (HTTP ${response.status})`, key))
  }

  return json
}

const MIME: Record<string, string> = {
  png: 'image/png',
  jpg: 'image/jpeg',
  jpeg: 'image/jpeg',
}

/** True for an image Meshy fetches itself: an http(s) URL or a data URI. */
export const isRemoteImage = (image: string) => /^(https?:|data:)/i.test(image)

/** The MIME type of a local image Meshy accepts, or an error. */
export const imageMime = (image: string) => {
  const mime = MIME[image.split('.').pop()?.toLowerCase() ?? '']
  if (!mime) throw new Error(`${image}: Meshy takes .png, .jpg or .jpeg images`)

  return mime
}

/** How an image argument shows in the pane: data URIs are not worth printing. */
export const describeImage = (image: string) =>
  image.startsWith('data:') ? '(data URI)' : image

