export type MeshyKind = 'image' | 'text' | 'multi'

export type MeshyStatus =
  | 'PENDING'
  | 'IN_PROGRESS'
  | 'DOWNLOADING'
  | 'SUCCEEDED'
  | 'FAILED'
  | 'CANCELED'

export type MeshyTask = {
  /** The id meshy_generate returned; names the GLB file. */
  id: string
  kind: MeshyKind
  /** The Meshy task being polled now (a text task's refine stage has its own). */
  apiId: string
  /** Text-to-3D only: which of the two stages is running. */
  stage?: 'preview' | 'refine'
  /** Text-to-3D only: start a refine (texturing) task once the preview succeeds. */
  shouldRefine?: boolean
  /** Refine request fields (enable_pbr, texture_prompt, ...). */
  refineOptions?: { [field: string]: string | number | boolean }
  status: MeshyStatus
  progress: number
  /** The prompt, or the image path or URL(s). */
  source: string
  /** The session directory the GLB is saved under. */
  cwd: string
  startedAt: number
  finishedAt?: number
  /** './meshy-models/<id>.glb' once downloaded. */
  file?: string
  error?: string
}

